74	+import { useEditor, useValue } from "tldraw";
75	+import { useArmedLibraryZoneId } from "./zoneHitTest";
76	+
77	+/**
78	+ * The library portal's arming visual (ticket 12) — a rotating pink/amber conic-gradient
79	+ * swirl with a faint dark veil, rendered over the library while a card drags over it.
80	+ * Local to the dragger (each browser computes its own armed state). Rendered via
81	+ * `TLComponents.InFrontOfTheCanvas` (viewport space, in front of the canvas layer)
82	+ * because the library's own opaque card-back picture sits on top of the zone shape
83	+ * itself — a look this fleet's `--armed-glow` ring can't reach through, and a
84	+ * deliberately distinct treatment from that ring (ticket 04's resolved design choice).
85	+ */
86	+export function LibraryPortalOverlay() {
87	+  const editor = useEditor();
88	+  const zoneId = useArmedLibraryZoneId(editor);
89	+
90	+  const rect = useValue(
91	+    "libraryPortalViewportRect",
92	+    () => {
93	+      if (!zoneId) return undefined;
94	+      const bounds = editor.getShapePageBounds(zoneId);
95	+      if (!bounds) return undefined;
96	+      const topLeft = editor.pageToViewport({ x: bounds.x, y: bounds.y });
97	+      const zoom = editor.getZoomLevel();
98	+      return { left: topLeft.x, top: topLeft.y, width: bounds.w * zoom, height: bounds.h * zoom };
99	+    },
100	+    [editor, zoneId]
101	+  );
102	+
103	+  if (!rect) return null;
104	+
105	+  return (
106	+    <div
107	+      data-testid="portal-arming"
108	+      style={{
109	+        position: "absolute",
110	+        left: rect.left,
111	+        top: rect.top,
112	+        width: rect.width,
113	+        height: rect.height,
114	+        overflow: "hidden",
115	+        pointerEvents: "none",
116	+      }}
117	+    >
118	+      <div
119	+        style={{
120	+          position: "absolute",
121	+          inset: "-30%",
122	+          background: "conic-gradient(from 0deg, var(--dark-pink), var(--armed-glow), var(--dark-pink))",
123	+          animation: "library-portal-swirl-spin 1.6s linear infinite",
124	+        }}
125	+      />
126	+      <div style={{ position: "absolute", inset: 0, background: "rgba(10, 6, 20, 0.4)" }} />
127	+      <style>{`
128	+        @keyframes library-portal-swirl-spin {
129	+          from { transform: rotate(0deg); }
130	+          to { transform: rotate(360deg); }
131	+        }
132	+      `}</style>
133	+    </div>
134	+  );
135	+}
