180	index 00000000..5ce4112c
181	--- /dev/null
182	+++ b/apps/tabletop/src/client/shapes/cardSwallow.ts
183	@@ -0,0 +1,106 @@
184	+import { Editor, TLShapeId } from "tldraw";
185	+import { MtgCardShape } from "../../shared/mtgCardShape";
186	+import { ZoneHit } from "./zoneHitTest";
187	+import { evictPassengers } from "./cardZoneEntry";
188	+
189	+const SWALLOW_DURATION_MS = 500;
190	+const SWALLOW_SPINS = 2;
191	+
192	+interface SwallowSnapshot {
193	+  x: number;
194	+  y: number;
195	+  rotation: number;
196	+  opacity: number;
197	+  props: MtgCardShape["props"];
198	+}
199	+
200	+/**
201	+ * The library portal's swallow (ticket 12): spins the card twice while shrinking and
202	+ * fading it into the library's center over ~500ms, then — send-then-commit — deletes it
203	+ * only once the Tabletop server confirms the Spine accepted `card.returned.v1`. On
204	+ * failure the card's visuals revert and it stays on the table; nothing here deletes
205	+ * synchronously, since tldraw non-null-asserts every still-settling shape in a
206	+ * multi-select drag (see `owners/tabletop-shape-mechanics`).
207	+ */
208	+export function swallowCard(editor: Editor, current: MtgCardShape, zoneHit: ZoneHit): void {
209	+  evictPassengers(editor, current, zoneHit);
210	+
211	+  const zoneBounds = editor.getShapePageBounds(zoneHit.id);
212	+  if (!zoneBounds) return;
213	+
214	+  const before: SwallowSnapshot = {
215	+    x: current.x,
216	+    y: current.y,
217	+    rotation: current.rotation,
218	+    opacity: current.opacity,
219	+    props: current.props,
220	+  };
221	+
222	+  editor.animateShapes(
223	+    [
224	+      {
225	+        id: current.id,
226	+        type: current.type,
227	+        x: zoneBounds.center.x - 0.5,
228	+        y: zoneBounds.center.y - 0.5,
229	+        rotation: current.rotation + SWALLOW_SPINS * 2 * Math.PI,
230	+        opacity: 0,
231	+        props: { ...current.props, w: 1, h: 1 },
232	+      },
233	+    ],
234	+    { animation: { duration: SWALLOW_DURATION_MS } }
235	+  );
236	+
237	+  const id = current.id;
238	+  const { owner, scryfallId, gameCardIndex } = current.props;
239	+
240	+  setTimeout(() => {
241	+    void completeSwallow(editor, id, before, { owner, scryfallId, gameCardIndex });
242	+  }, 0);
243	+}
244	+
245	+async function completeSwallow(
246	+  editor: Editor,
247	+  id: TLShapeId,
248	+  before: SwallowSnapshot,
249	+  send: { owner: string; scryfallId: string; gameCardIndex: number | null }
250	+): Promise<void> {
251	+  const [ok] = await Promise.all([postCardReturned(send), sleep(SWALLOW_DURATION_MS)]);
252	+
253	+  if (!editor.getShape(id)) return; // already gone (e.g. store reset mid-flight)
254	+
255	+  if (ok) {
256	+    editor.deleteShapes([id]);
257	+  } else {
258	+    editor.animateShapes(
259	+      [{ id, type: "mtg-card", x: before.x, y: before.y, rotation: before.rotation, opacity: before.opacity, props: before.props }],
260	+      { animation: { duration: 200 } }
261	+    );
262	+  }
263	+}
264	+
265	+function sleep(ms: number): Promise<void> {
266	+  return new Promise((resolve) => setTimeout(resolve, ms));
267	+}
268	+
269	+function tableSlugFromLocation(): string | undefined {
270	+  const match = window.location.pathname.match(/^\/t\/([^/]+)$/);
271	+  return match ? decodeURIComponent(match[1]) : undefined;
272	+}
273	+
274	+async function postCardReturned(send: { owner: string; scryfallId: string; gameCardIndex: number | null }): Promise<boolean> {
275	+  if (send.gameCardIndex === null) return false;
276	+  const tableSlug = tableSlugFromLocation();
277	+  if (!tableSlug) return false;
278	+
279	+  try {
280	+    const response = await fetch(`/api/tables/${encodeURIComponent(tableSlug)}/cards/return`, {
281	+      method: "POST",
282	+      headers: { "content-type": "application/json" },
283	+      body: JSON.stringify({ seatId: send.owner, scryfallId: send.scryfallId, gameCardIndex: send.gameCardIndex }),
284	+    });
285	+    return response.ok;
286	+  } catch {
287	+    return false;
288	+  }
289	+}
