374	diff --git a/apps/tabletop/src/server/cardReturned.ts b/apps/tabletop/src/server/cardReturned.ts
375	new file mode 100644
376	index 00000000..95f50edc
377	--- /dev/null
378	+++ b/apps/tabletop/src/server/cardReturned.ts
379	@@ -0,0 +1,70 @@
380	+import { Request, Response } from "express";
381	+import { trace } from "@opentelemetry/api";
382	+import { getOrCreateRoom } from "./rooms.js";
383	+import { slugifyTableName, tableNameFromSlug } from "../shared/slugify.js";
384	+import { sendCardReturnedToSpineBestEffort } from "./sendCardReturned.js";
385	+
386	+interface CardReturnedRequestBody {
387	+  seatId?: string;
388	+  scryfallId?: string;
389	+  gameCardIndex?: number;
390	+  fromZone?: string;
391	+}
392	+
393	+/**
394	+ * The library-portal swallow's send leg (ticket 12): the client has already decided to
395	+ * swallow a card and needs a 2xx before it commits the shape's deletion (send-then-commit).
396	+ * The client only knows the card's own props (`owner`, `scryfallId`, `gameCardIndex`) — it
397	+ * has no notion of its own player identity, matching the rest of this ship's shared-canvas
398	+ * design — so `seatId` here is the card's owner, and `playerName`/the Spine's real
399	+ * `tableId` are resolved server-side from the room registry, the same lookup
400	+ * `handleSeatJoined` already does.
401	+ */
402	+export async function handleCardReturned(req: Request, res: Response): Promise<void> {
403	+  const tableName = slugifyTableName(req.params.tableName ?? "");
404	+  if (!tableName) {
405	+    res.status(400).json({ error: "table name required" });
406	+    return;
407	+  }
408	+
409	+  const body = req.body as CardReturnedRequestBody;
410	+  const { seatId, scryfallId, gameCardIndex, fromZone } = body;
411	+  if (!seatId || !scryfallId || typeof gameCardIndex !== "number") {
412	+    res.status(400).json({ error: "seatId, scryfallId, and gameCardIndex are required" });
413	+    return;
414	+  }
415	+
416	+  const entry = getOrCreateRoom(tableName);
417	+  if (!entry.spineTableId) {
418	+    res.status(409).json({ error: "table has no live Spine subscription yet" });
419	+    return;
420	+  }
421	+  const playerArea = entry.seats.get(seatId);
422	+  if (!playerArea) {
423	+    res.status(404).json({ error: "seat not found on this table" });
424	+    return;
425	+  }
426	+
427	+  trace.getActiveSpan()?.setAttributes({
428	+    "table.name": tableNameFromSlug(tableName),
429	+    "table.slug": tableName,
430	+    "seat.id": seatId,
431	+    "card.scryfall_id": scryfallId,
432	+    "card.game_card_index": gameCardIndex,
433	+  });
434	+
435	+  const ok = await sendCardReturnedToSpineBestEffort({
436	+    tableId: entry.spineTableId,
437	+    seatId,
438	+    playerName: playerArea.playerName,
439	+    scryfallId,
440	+    gameCardIndex,
441	+    ...(fromZone !== undefined ? { fromZone } : {}),
442	+  });
443	+
444	+  if (ok) {
445	+    res.status(200).json({ ok: true });
446	+  } else {
447	+    res.status(502).json({ ok: false, error: "the Spine did not confirm the card.returned event" });
448	+  }
449	+}
