786	@@ -0,0 +1,33 @@
787	+import http from "node:http";
788	+
789	+/**
790	+ * A minimal stand-in for the Spine's generic events endpoint, listening on the default
791	+ * `SPINE_URL` port (4600) for the duration of a Playwright run. `verify.sh` starts the
792	+ * Tabletop server with no live Spine to talk to; without this, any send-then-commit flow
793	+ * that awaits a real 2xx (the library-portal swallow, ticket 12) can never complete in
794	+ * verification. Accepts every `POST /tables/:tableId/events` with 201 — good enough for
795	+ * specs that only need "the Spine confirmed," not specs that need to inspect what was sent.
796	+ */
797	+let server: http.Server | undefined;
798	+
799	+export function startFakeSpine(port = 4600): Promise<void> {
800	+  server = http.createServer((req, res) => {
801	+    let raw = "";
802	+    req.on("data", (chunk) => (raw += chunk));
803	+    req.on("end", () => {
804	+      res.writeHead(201, { "content-type": "application/json" });
805	+      res.end(JSON.stringify({ ok: true }));
806	+    });
807	+  });
808	+  return new Promise((resolve, reject) => {
809	+    server!.once("error", reject);
810	+    server!.listen(port, resolve);
811	+  });
812	+}
813	+
814	+export function stopFakeSpine(): Promise<void> {
815	+  return new Promise((resolve) => {
816	+    if (!server) return resolve();
817	+    server.close(() => resolve());
818	+  });
819	+}
